/*
 *  Sends the test parameter structure and number of tests
 */
void
AUDIOLIB_mute_getTestParams (AUDIOLIB_mute_testParams_t ** params, int32_t * numTests)
{
   *params = testParams;
   *numTests = sizeof (testParams) / sizeof (AUDIOLIB_mute_testParams_t);
}
